fn toggle_case(s: Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len());
    
    for ch in s {
        let code = ch as u32;
        
        let toggled = if code >= 97 && code <= 122 {
            // ASCII lowercase: convert to uppercase
            char::from_u32(code - 32).unwrap()
        } else if code >= 65 && code <= 90 {
            // ASCII uppercase: convert to lowercase
            char::from_u32(code + 32).unwrap()
        } else {
            // Not an ASCII letter: keep unchanged
            ch
        };
        
        result.push(toggled);
    }
    
    result
}